[
  {
    "path": "tools.opencode.read_mcp_resource",
    "description": "Read one MCP resource by server and URI. Not for local files. Always return the full contents rather than slicing or filtering them; oversized output is truncated automatically and the full content is saved to a file you can read. Images and PDFs are shown to you directly.",
    "signature": "tools.opencode.read_mcp_resource({
  /** The server field of the discovered resource. */
  server: string,
  /** Exact resource URI from discovery, an expanded uriTemplate, or the user. */
  uri: string,
}): Promise<{
  server: string,
  uri: string,
  contents: Array<{
        type: "text",
        uri: string,
        text: string,
        mimeType?: string,
      } | {
        type: "blob",
        uri: string,
        blob: string,
        mimeType?: string,
      }>,
}>"
  },
  {
    "path": "tools.opencode.list_mcp_resources",
    "description": "List documents, records, and other data exposed by MCP servers. Use this when the user refers to something that is not a local file, such as a URI with a custom scheme, then load a match with read_mcp_resource. Each entry names the server to read it from. Templates are resources addressed by a parameter such as a record ID; fill in the uriTemplate placeholders before reading.",
    "signature": "tools.opencode.list_mcp_resources({
  /** MCP server name as configured. Omit to list every server. */
  server?: string,
}): Promise<{
  resources: Array<{
      server: string,
      name: string,
      uri: string,
      description?: string,
      mimeType?: string,
    }>,
  templates: Array<{
      server: string,
      name: string,
      uriTemplate: string,
      description?: string,
      mimeType?: string,
    }>,
}>"
  },
  {
    "path": "tools.opencode.models",
    "description": "Search the models available to use. Use this to turn a model name the user mentions into an exact reference before running a subagent on it. Check your own provider first.",
    "signature": "tools.opencode.models({
  /** Text to search for in model names and IDs. */
  query?: string,
  /** Provider ID or name to filter by. Try your own provider first. */
  provider?: string,
  /** Include older versions of each model family. By default only the newest version is listed. */
  all?: boolean,
  /** Maximum number of models to return. Defaults to 20. @integer @minimum 1 @maximum 100 */
  limit?: number,
  /** Number of models to skip, for paging through results. @integer @minimum 0 */
  offset?: number,
}): Promise<{
  /** Matching models grouped by provider. Your own provider comes first. */
  providers: Array<{
      id: string,
      name: string,
      /** Newest first. */
      models: Array<{
          /** providerID/modelID */
          id: string,
          name: string,
          /** Release date as a Unix timestamp in milliseconds, or 0 when unknown. */
          released: number,
          variants: Array<string>,
          /** Pricing in USD per million tokens. */
          cost: Array<{
              tier?: {
                type: "context",
                /** @integer */
                size: number,
              },
              input: number,
              output: number,
              cache: {
                read: number,
                write: number,
              },
            }>,
          status: "alpha" | "beta" | "deprecated" | "active",
        }>,
    }>,
  /** Number of matching models across all pages. @integer */
  total: number,
  /** Offset of the next page, or null on the last page. */
  next: number | null,
}>"
  },
  {
    "path": "tools.opencode.session_move",
    "description": "Move a session to another directory, or omit sessionID to move the current session. The current session moves at the next safe boundary; do not run destination-dependent tools in the same execute call.",
    "signature": "tools.opencode.session_move({
  /** Omit to move the current session. @pattern ^ses */
  sessionID?: string,
  /** Destination directory, relative to the target session's directory or absolute. Supports ~. @minLength 1 */
  directory: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  directory: string,
}>"
  },
  {
    "path": "tools.opencode.session_rename",
    "description": "Rename a session, or omit sessionID to rename the current session. Use a short, specific title that summarizes the work being done.",
    "signature": "tools.opencode.session_rename({
  /** Omit to rename the current session. @pattern ^ses */
  sessionID?: string,
  /** New session title. @minLength 1 */
  title: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  title: string,
}>"
  },
  {
    "path": "tools.opencode.worktree_create",
    "description": "Create a named worktree. Returns its directory.",
    "signature": "tools.opencode.worktree_create({
  name: string,
}): Promise<{
  directory: string,
}>"
  },
  {
    "path": "tools.opencode.worktree_list",
    "description": "List a repository's worktrees.",
    "signature": "tools.opencode.worktree_list(): Promise<{
  worktrees: Array<{
      directory: string,
      strategy?: string,
    }>,
}>"
  },
  {
    "path": "tools.opencode.worktree_remove",
    "description": "Remove a worktree. The repository location selects configuration; directory identifies the worktree to remove.",
    "signature": "tools.opencode.worktree_remove({
  /** Absolute path of the worktree to remove. @minLength 1 */
  directory: string,
  /** Discard modified and untracked files. Only set this when the user has confirmed forced removal. */
  force?: boolean,
}): Promise<{
  directory: string,
  removed: boolean,
}>"
  },
  {
    "path": "tools.playwright.browser_click",
    "description": "Perform click on a web page",
    "signature": "tools.playwright.browser_click({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target: string,
  /** Whether to perform a double click instead of a single click */
  doubleClick?: boolean,
  /** Button to click, defaults to left */
  button?: "left" | "right" | "middle",
  /** Modifier keys to press */
  modifiers?: Array<"Alt" | "Control" | "ControlOrMeta" | "Meta" | "Shift">,
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_drag",
    "description": "Perform drag and drop between two elements",
    "signature": "tools.playwright.browser_drag({
  /** Human-readable source element description used to obtain the permission to interact with the element */
  startElement?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  startTarget: string,
  /** Human-readable target element description used to obtain the permission to interact with the element */
  endElement?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  endTarget: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_drop",
    "description": "Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of "paths" or "data" must be provided.",
    "signature": "tools.playwright.browser_drop({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target: string,
  /** Absolute paths to files to drop onto the element. */
  paths?: Array<string>,
  /**
   * Data to drop, as a map of MIME type to string value (e.g. {"text/plain": "hello", "text/uri-list": "https://example.com"}).
   */
  data?: {
    [key: string]: string,
  },
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_evaluate",
    "description": "Evaluate JavaScript expression on page or element",
    "signature": "tools.playwright.browser_evaluate({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target?: string,
  /** () => { /* code * / } or (element) => { /* code * / } when element is provided */
  function: string,
  /**
   * File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text.
   */
  filename?: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_hover",
    "description": "Hover over element on page",
    "signature": "tools.playwright.browser_hover({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_select_option",
    "description": "Select an option in a dropdown",
    "signature": "tools.playwright.browser_select_option({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target: string,
  /** Array of values to select in the dropdown. This can be a single value or multiple values. */
  values: Array<string>,
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_take_screenshot",
    "description": "Take a screenshot of the current page. You can't perform actions based on the screenshot, use browser_snapshot for actions.",
    "signature": "tools.playwright.browser_take_screenshot({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target?: string,
  /** Image format for the screenshot. If unset, inferred from the filename extension, otherwise png. */
  type?: "png" | "jpeg" | "webp",
  /**
   * File name to save the screenshot to. Relative file names are resolved against the workspace root. If not specified, the screenshot is saved into the output directory as `page-{timestamp}.{png|jpeg|webp}`.
   */
  filename?: string,
  /**
   * When true, takes a screenshot of the full scrollable page, instead of the currently visible viewport. Cannot be used with element screenshots.
   */
  fullPage?: boolean,
  /**
   * Image resolution scale. "css" produces a screenshot sized in CSS pixels (smaller, consistent across devices). "device" produces a high-resolution screenshot using device pixels (larger, accounts for the device pixel ratio). Default is css.
   * @default "css"
   */
  scale: "css" | "device",
}): Promise<unknown>"
  },
  {
    "path": "tools.playwright.browser_type",
    "description": "Type text into editable element",
    "signature": "tools.playwright.browser_type({
  /** Human-readable element description used to obtain permission to interact with the element */
  element?: string,
  /** Exact target element reference from the page snapshot, or a unique element selector */
  target: string,
  /** Text to type into the element */
  text: string,
  /** Whether to submit entered text (press Enter after) */
  submit?: boolean,
  /**
   * Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once.
   */
  slowly?: boolean,
}): Promise<unknown>"
  }
]

